import time
import email.utils
from datetime import datetime, timezone
from urllib.request import Request, urlopen
from urllib.error import HTTPError


class MeridianClient:
    """HTTP client for the Meridian payments API."""

    def __init__(self, base_url: str, api_key: str) -> None:
        self._base_url = base_url.rstrip("/")
        self._api_key = api_key
        self._etag: str | None = None

    def _headers(self, extra: dict[str, str] | None = None) -> dict[str, str]:
        h: dict[str, str] = {
            "Authorization": f"Bearer {self._api_key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        }
        if extra:
            h.update(extra)
        return h

    def _handle_429(self, resp: HTTPError) -> None:
        raw = resp.headers.get("Retry-After")
        if raw is None:
            time.sleep(1)
            return
        try:
            seconds = float(raw.strip())
            if seconds > 0:
                time.sleep(seconds)
        except ValueError:
            dt = email.utils.parsedate_to_datetime(raw)
            wait = (dt - datetime.now(timezone.utc)).total_seconds()
            if wait > 0:
                time.sleep(wait)

    def _request_with_retry(self, req: Request, allow_etag: bool = False) -> tuple[int, dict | None, dict[str, str]]:
        """Send a request with 429 retry logic. Returns (status, json_body_or_None, headers_dict)."""
        attempt = 0
        while True:
            attempt += 1
            try:
                resp = urlopen(req)
                status = resp.getcode()
                hdrs = dict(resp.headers)
                body = resp.read().decode("utf-8") if resp.length else ""
                data = json.loads(body) if body else None
                return status, data, hdrs
            except HTTPError as e:
                hdrs = dict(e.headers)
                if e.code == 429:
                    self._handle_429(e)
                    continue
                body = e.read().decode("utf-8", errors="replace") if e.fp else ""
                data = json.loads(body) if body else None
                return e.code, data, hdrs

    def fetch_all_payments(self) -> list[dict]:
        """Cursor-paginate all payments from the API, returning them sorted oldest-first by UTC created_at."""
        cursor: str | None = None
        all_items: list[dict] = []
        first_page = True

        while True:
            params = []
            if cursor is not None:
                params.append(f"cursor={cursor}")
            if params:
                url = f"{self._base_url}/v1/payments?{'&'.join(params)}"
            else:
                url = f"{self._base_url}/v1/payments"

            extra_headers: dict[str, str] = {}
            if first_page and self._etag is not None:
                extra_headers["If-None-Match"] = self._etag

            req = Request(url, headers=self._headers(extra_headers))
            status, data, hdrs = self._request_with_retry(req)

            # Update ETag cache from any response that provides one
            new_etag = hdrs.get("ETag")
            if new_etag is not None:
                self._etag = new_etag

            first_page = False

            # 304 Not Modified on first request -> nothing changed
            if status == 304:
                return []

            # 410 Gone -> cursor expired, restart from page 1
            if status == 410:
                all_items.clear()
                cursor = None
                first_page = True
                continue

            if status != 200 or data is None:
                raise RuntimeError(f"Unexpected response {status} from /v1/payments")

            items = data.get("data", [])
            next_cursor = data.get("next_cursor")

            all_items.extend(items)

            if next_cursor is None:
                break
            cursor = next_cursor

        # Normalize and sort by UTC created_at
        def utc_key(p: dict) -> datetime:
            raw = p["created_at"]
            dt = datetime.fromisoformat(raw)
            return dt.astimezone(timezone.utc)

        all_items.sort(key=utc_key)
        return all_items

    def total_count(self) -> int:
        """Return the total number of payments in the collection according to the API."""
        url = f"{self._base_url}/v1/payments?limit=1"
        req = Request(url, headers=self._headers())
        status, data, _ = self._request_with_retry(req)

        if status != 200 or data is None:
            raise RuntimeError(f"Unexpected response {status} from /v1/payments")

        return int(data.get("total", 0))

    def create_payment(self, amount_minor: int, currency: str, idempotency_key: str) -> str:
        """Create a payment via the API using an idempotency key, returning the resulting payment id."""
        url = f"{self._base_url}/v1/payments"
        body = json.dumps({"amount_minor": amount_minor, "currency": currency}).encode("utf-8")

        req = Request(
            url,
            data=body,
            headers=self._headers({"Idempotency-Key": idempotency_key}),
            method="POST",
        )
        status, data, _ = self._request_with_retry(req)

        if status == 201:
            return str(data["id"])
        if status == 409 and data is not None and data.get("error") == "duplicate":
            return str(data["payment_id"])

        raise RuntimeError(f"Unexpected response {status} from POST /v1/payments")
